#include <psx/situation/protocol.hpp>
#include <algorithm>
#include <stdexcept>
namespace psx::situation {namespace n=psx::non_normal;
Client::Client(ProcessIdentity target):target_(target),self_(n::current_process()),session_(n::nonce()),frequency_(n::qpc_frequency()){}
Client::~Client(){disconnect();}
void Client::disconnect()noexcept{if(pipe_!=INVALID_HANDLE_VALUE){CloseHandle(pipe_);pipe_=INVALID_HANDLE_VALUE;}sent_=received_=0;}
void Client::connect(){disconnect();const auto name=endpoint(target_);const auto deadline=GetTickCount64()+1000;do{pipe_=CreateFileW(name.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr);if(pipe_!=INVALID_HANDLE_VALUE)break;const auto error=GetLastError();const auto now=GetTickCount64();if(now>=deadline||(error!=ERROR_PIPE_BUSY&&error!=ERROR_FILE_NOT_FOUND))break;if(error==ERROR_PIPE_BUSY)WaitNamedPipeW(name.c_str(),static_cast<DWORD>(std::min<std::uint64_t>(100,deadline-now)));else Sleep(10);}while(GetTickCount64()<deadline);ProcessIdentity actual{};if(pipe_==INVALID_HANDLE_VALUE||!n::authenticate(pipe_,false,target_,actual)){disconnect();throw std::runtime_error("situation service unavailable or peer identity changed");}}
Request Client::request(Command c,std::uint64_t operation,std::uint64_t life){Request r;r.command=c;r.client=self_;r.target=target_;r.session=session_;r.operation=operation;r.lifecycle=life;r.frequency=frequency_;r.issued_qpc=n::qpc();r.deadline_qpc=r.issued_qpc+static_cast<std::int64_t>(frequency_*30);return r;}
Result Client::exchange(Request r){if(pipe_==INVALID_HANDLE_VALUE)throw std::runtime_error("situation service disconnected");Frame f;if(sent_==UINT32_MAX||!encode(r,++sent_,f)||!write_frame(pipe_,f)||!read_frame(pipe_,f,1500)) {disconnect();throw std::runtime_error("situation transport outcome uncertain; use operation lookup, never replay");}Result result;std::uint32_t seq{};if(!decode({f.bytes.data(),f.size},result,seq)||seq<=received_||result.server!=target_||result.session!=session_||result.operation!=r.operation){disconnect();throw std::runtime_error("situation response identity");}received_=seq;return result;}
Result Client::status(){return exchange(request(Command::status,++next_));}
Result Client::lookup(std::uint64_t op){return exchange(request(Command::lookup,op));}
Result Client::wait(std::uint64_t op,std::uint32_t timeout){auto end=GetTickCount64()+timeout;Result r;do{r=lookup(op);if(r.phase!=Phase::accepted)return r;Sleep(20);}while(GetTickCount64()<end);return r;}
Result Client::capture(std::vector<std::uint8_t>& artifact){auto state=status();auto operation=++next_;last_mutation_=operation;auto r=exchange(request(Command::capture,operation,state.lifecycle));if(r.phase==Phase::accepted)r=wait(operation);artifact.clear();if(r.phase!=Phase::saved_verified)return r;return fetch_capture(operation,artifact);}
Result Client::fetch_capture(std::uint64_t operation,std::vector<std::uint8_t>& artifact){auto r=lookup(operation);artifact.clear();if(r.phase!=Phase::saved_verified)return r;artifact.reserve(r.total);for(std::uint32_t offset=0;offset<r.total;){auto q=request(Command::fetch,operation);q.offset=offset;q.total=r.total;auto part=exchange(q);if(part.phase!=Phase::saved_verified||part.total!=r.total||part.artifact_hash!=r.artifact_hash||part.offset!=offset||part.data.empty()||part.data.size()>r.total-offset)throw std::runtime_error("capture artifact no longer retained");artifact.insert(artifact.end(),part.data.begin(),part.data.end());offset+=static_cast<std::uint32_t>(part.data.size());}if(artifact.size()!=r.total||sha256(artifact)!=r.artifact_hash)throw std::runtime_error("capture artifact identity");validate_native(inspect(artifact));return r;}
Result Client::recall(std::span<const std::uint8_t> artifact,std::uint64_t life,bool fmc){if(fmc)decode_fmc(artifact);else validate_native(inspect(artifact));auto operation=++next_;last_mutation_=operation;for(std::size_t offset=0;offset<artifact.size();){auto q=request(Command::stage,operation,life);q.total=static_cast<std::uint32_t>(artifact.size());q.offset=static_cast<std::uint32_t>(offset);auto nbytes=std::min(chunk_bytes,artifact.size()-offset);q.data.assign(artifact.begin()+offset,artifact.begin()+offset+nbytes);auto r=exchange(q);if(r.phase!=Phase::accepted)return r;offset+=nbytes;}auto r=exchange(request(fmc?Command::recall_fmc:Command::recall,operation,life));if(r.phase==Phase::accepted)r=wait(operation);if(r.phase==Phase::observed&&r.artifact_hash!=sha256(artifact))throw std::runtime_error("recall artifact identity");return r;}
}
